<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$ref=preg_replace('/[^A-Za-z0-9._-]/','',(string)($_GET['reference']??''));$s=$db->prepare("SELECT ip.*,i.invoice_number,i.title,l.name client_name,l.company,l.email FROM invoice_payments ip JOIN invoices i ON i.id=ip.invoice_id JOIN leads l ON l.id=ip.lead_id WHERE ip.reference=? LIMIT 1");$s->execute([$ref]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Payment not found.');}$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');function rm($v,$c){return $c.' '.number_format((float)$v,2);} ?><!doctype html><html><head><meta charset="utf-8"><title>Payment Receipt <?=$e($p['reference'])?></title><style>@page{size:A4;margin:18mm}body{font-family:Arial;color:#222}.box{max-width:760px;margin:auto;border:1px solid #ddd;padding:40px}.row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #eee}.success{font-size:20px;font-weight:bold}.actions{margin-top:30px}@media print{.actions{display:none}}</style></head><body><div class="box"><h1>Distinguished Web Services</h1><h2>Payment Receipt</h2><p class="success">Payment <?=$e($p['status'])?></p><div class="row"><span>Reference</span><strong><?=$e($p['reference'])?></strong></div><div class="row"><span>Invoice</span><strong><?=$e($p['invoice_number'])?></strong></div><div class="row"><span>Client</span><strong><?=$e($p['client_name'])?></strong></div><div class="row"><span>Email</span><span><?=$e($p['email'])?></span></div><div class="row"><span>Amount</span><strong><?=rm($p['amount'],$p['currency'])?></strong></div><div class="row"><span>Gateway</span><span><?=$e($p['gateway'])?></span></div><div class="row"><span>Transaction ID</span><span><?=$e($p['gateway_transaction_id']?:'—')?></span></div><div class="row"><span>Date</span><span><?=$e($p['paid_at']?:$p['created_at'])?></span></div><div class="actions"><a href="#" onclick="window.print();return false">Print / Save as PDF</a></div></div></body></html>